/*!
 * wega-music-endless2.js - ENDLESS add-on for the Wega's Challenge music pack.
 * The game loads it by itself when an ENDLESS run needs it (it is not in index.html): it registers a lazy
 * "endless2" track with WegaMusic, decoded only while it plays. The music changes every 10 floors
 * (Endless, then Endless 1-5); the shop between floors has its own theme.
 * ENDLESS 2 (floors 21-30) - supplied by the player. Loops with a crossfade from 293.4 s (where its reverb tail starts) back to the top.
 */
(function (global) {
  "use strict";
  var D = global.WEGA_MUSIC_DATA, W = global.WegaMusic;
  if (!D || !W) { if (global.console) console.warn("[wega-music-endless2.js] load wega-music.js first"); return; }
  D.endless2 = {
    title: "ENDLESS 2 (floors 21-30)",
    credit: "supplied by the player",
    duration: 296.986,
    loopStart: 0.0,
    loopEnd: 293.4,
    xfade: 2.5,
    gain: 0.9,
    lazy: true,
    src: "data:audio/mpeg;base64,"
  };
  if (W.tracks.indexOf("endless2") < 0) W.tracks.push("endless2");
  if (W.onPack) W.onPack("endless2");
})(typeof window !== "undefined" ? window : globalThis);
